const splitItems = $('Split Templates').all();

const secretRegexes = [
  /sk-[a-zA-Z0-9]{20,}/i,
  /bearer\s+[a-zA-Z0-9\-\._~\+\/]+=*/i,
  /(A3T[A-Z0-9]|AKIA|AGPA|AIDA|AROA|AIPA|ANPA|ANVA|ASIA)[A-Z0-9]{16}/,
  /ghp_[a-zA-Z0-9]{36}|github_pat_[a-zA-Z0-9]{22}_[a-zA-Z0-9]{59}/,
  /AIza[0-9A-Za-z-_]{35}/,
  /xox[baprs]-[0-9a-zA-Z]{10,48}/,
  /(postgres|mysql|mongodb|redis):\/\/[^:]+:[^@]+@/i
];

// Strips surrogate pairs (emojis), lone surrogates, null bytes, and control chars
function sanitizeString(str) {
  if (typeof str !== 'string') return str;

  let s = str;

  // 1. Remove 4-byte surrogate pairs (emojis, symbols) to prevent Text Splitter truncation errors
  s = s.replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]/g, ' ');

  // 2. Remove any remaining orphan surrogates
  s = s.replace(/[\uD800-\uDFFF]/g, '');

  // 3. Strip null bytes and non-printable control characters (preserving newlines/tabs)
  s = s.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '');

  return s;
}

function sanitize(val) {
  if (typeof val === 'string') {
    return sanitizeString(val);
  }
  if (Array.isArray(val)) {
    return val.map(sanitize);
  }
  if (val && typeof val === 'object') {
    const res = {};
    for (const [k, v] of Object.entries(val)) {
      res[k] = sanitize(v);
    }
    return res;
  }
  return val;
}

return $input.all().map((item, index) => {
  const fullData = item.json || {};
  const splitData = splitItems[index]?.json || {};

  const workflowObj = fullData.workflow || {};
  const nodes = fullData.nodes || workflowObj.nodes || [];

  const rawId = fullData.id ?? fullData.templateId ?? splitData.id;
  const templateId = rawId ? Number(rawId) : null;

  const name = fullData.name || splitData.name || 'Untitled';
  const description = fullData.description || splitData.description || '';

  const rawCategories = fullData.categories || splitData.categories || [];
  const categories = rawCategories.map(c => typeof c === 'object' ? (c.name || c.label || '') : c).filter(Boolean);

  const nodeTypes = [...new Set(nodes.map(n => n.type))];
  const nodeCount = nodes.length;

  const triggerTypes = [...new Set(
    nodes.filter(n => (n.type || '').toLowerCase().includes('trigger')).map(n => n.type)
  )];

  const hasAiNodes = nodes.some(n => 
    (n.type || '').includes('langchain') || 
    (n.type || '').includes('openai') || 
    (n.type || '').includes('anthropic') || 
    (n.type || '').includes('ollama') || 
    (n.type || '').includes('qdrant') ||
    (n.type || '').includes('vectorStore')
  );

  const views = Number(fullData.views ?? splitData.views ?? fullData.totalViews ?? 0);
  const createdAt = fullData.createdAt || splitData.createdAt || fullData.created_at || null;
  const slug = fullData.slug || splitData.slug || '';
  const templateUrl = slug ? `https://n8n.io/workflows/${slug}` : (templateId ? `https://n8n.io/workflows/${templateId}` : '');

  const stickyNotes = nodes
    .filter(n => n.type === 'n8n-nodes-base.stickyNote')
    .map(n => n.parameters?.content || '');

  const systemPrompts = nodes
    .filter(n => n.parameters?.options?.systemMessage || n.parameters?.systemMessage)
    .map(n => n.parameters?.options?.systemMessage || n.parameters?.systemMessage || '');

  const nodeDetails = nodes.map(n => {
    return `Node: ${n.name} (${n.type})\nConfig: ${JSON.stringify(n.parameters || {})}`;
  }).join('\n');

  const pageContent = [
    `Title: ${name}`,
    `Description: ${description || 'No description provided'}`,
    `Categories: ${categories.join(', ')}`,
    `Node Types Used: ${nodeTypes.join(', ')}`,
    stickyNotes.length > 0 ? `Sticky Notes:\n${stickyNotes.join('\n')}` : '',
    systemPrompts.length > 0 ? `System Prompts:\n${systemPrompts.join('\n')}` : '',
    nodeDetails ? `Workflow Configurations:\n${nodeDetails}` : ''
  ].filter(Boolean).join('\n\n');

  const paramString = JSON.stringify(nodes.map(n => n.parameters || {}));
  const combinedTextToScan = [
    paramString,
    stickyNotes.join(' '),
    systemPrompts.join(' '),
    description
  ].join(' ');

  const hasSecurityWarning = secretRegexes.some(regex => regex.test(combinedTextToScan));

  const payload = {
    metadata: {
      template_id: templateId,
      name: name,
      description: description,
      categories: categories,
      nodeTypes: nodeTypes,
      node_count: nodeCount,
      trigger_types: triggerTypes,
      has_ai_nodes: hasAiNodes,
      has_security_warning: hasSecurityWarning,
      views: views,
      created_at: createdAt,
      template_url: templateUrl
    },
    pageContent: pageContent
  };

  return {
    json: sanitize(payload)
  };
});
